-- State transitions declared for PurchaseReceipt: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION inventory.purchase_receipts_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('draft', 'submitted'), ('submitted', 'cancelled'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: purchase_receipts.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_purchase_receipts__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS purchase_receipts_status_transition_check ON inventory.purchase_receipts;
CREATE TRIGGER purchase_receipts_status_transition_check
    BEFORE UPDATE OF "status" ON inventory.purchase_receipts
    FOR EACH ROW EXECUTE FUNCTION inventory.purchase_receipts_status_transition_check();
